  public static JWTToken encode(String header, String payloadAsString, String secretKey) {
    var headers = parse(header);
    var payload = parse(payloadAsString);

    var builder =
        JWTToken.builder()	//fqn: JWTToken.builder
            .header(write(header, headers))
            .payload(write(payloadAsString, payload))
            .validHeader(!hasText(header) || !headers.isEmpty())	//fqn: java.util.Map.isEmpty
            .validToken(true)
            .validPayload(!hasText(payloadAsString) || !payload.isEmpty());	//fqn: java.util.Map.isEmpty

    JsonWebSignature jws = new JsonWebSignature();
    jws.setPayload(payloadAsString);	//fqn: jws.setPayload
    headers.forEach((k, v) -> jws.setHeader(k, v));	//fqn: java.util.Map.forEach
    if (!headers.isEmpty()) { // otherwise e30 meaning {} will be shown as header	//fqn: java.util.Map.isEmpty
      builder.encoded(	//fqn: builder.encoded
          CompactSerializer.serialize(	//fqn: CompactSerializer.serialize
              new String[] {jws.getHeaders().getEncodedHeader(), jws.getEncodedPayload()}));	//fqn: jws.getHeaders
    }

    // Only sign when valid header and payload
    if (!headers.isEmpty() && !payload.isEmpty() && hasText(secretKey)) {	//fqn: java.util.Map.isEmpty
      jws.setDoKeyValidation(false);	//fqn: jws.setDoKeyValidation
      jws.setKey(new HmacKey(secretKey.getBytes(UTF_8)));	//fqn: java.lang.String.getBytes
      try {
        builder.encoded(jws.getCompactSerialization());	//fqn: builder.encoded
        builder.signatureValid(true);	//fqn: builder.signatureValid
      } catch (JoseException e) {
        // Do nothing
      }
    }
    return builder.build();	//fqn: builder.build
  }

